  name: 'EffortsSettings',
  props: {
    /** Global settings object (kept for symmetry with the other panels). */
    settings: { type: Object, default: null }
  },
  data() {
    return {
      efforts: [],
      fields: [],
      groups: [],
      tiers: ['agile', 'max', 'default'],
