          !(Array.isArray(value) && !value.length)
      ).length
    }
  },
  watch: {
    settings: {
      immediate: true,
      handler() {
        this.load()
      }
    }
  },
  methods: {
    api() {
      return this.$project?.$api?.efforts
    },
    /** Load the definitions and the field documentation. */
    async load() {
      const api = this.api()
      if (!api) {
        this.error = 'Efforts API not available for this project'
        return
      }
      if (this.loading) return
      this.loading = true
      this.error = null
      try {
        const [efforts, docs] = await Promise.all([
          api.list(),
          this.fields.length ? Promise.resolve(null) : api.fields().catch(() => null)
        ])
        this.efforts = efforts || []
        if (docs) {
          this.fields = docs.fields || []
          this.groups = docs.groups || []
          this.tiers = docs.tiers || this.tiers
        }
        const current = this.efforts.find(item => item.name === this.draft.name)
        const next = current || this.efforts[0] || null
        if (next) this.edit(next)
        else this.newEffort()
      } catch (error) {
        this.error = error?.message || 'Could not load the efforts'
      } finally {
        this.loading = false
      }
    },
    fieldsOf(group) {
      return this.fields.filter(field => field.group === group)
    },
    toggleHelp(key) {
      this.help = { ...this.help, [key]: !this.help[key] }
    },
    edit(effort) {
      this.isNew = false
      this.draft = {
        name: effort.name,
        description: effort.description || '',
        tier: effort.tier || 'agile',
        values: { ...(effort.values || {}) },
        builtin: !!effort.builtin,
        profiles: effort.profiles || []
      }
    },
    newEffort() {
      this.isNew = true
      this.draft = EMPTY_DRAFT()
    },
    setValue(key, value, control) {
      const values = { ...this.draft.values }
      if (control === 'toggle') {
        values[key] = value
      } else if (control === 'list') {
        const list = String(value || '')
          .split(',')
          .map(item => item.trim())
          .filter(Boolean)
        values[key] = list.length ? list : null
      } else if (String(value).trim() === '') {
        values[key] = null
      } else if (control === 'number') {
        const parsed = Number(value)
        values[key] = Number.isNaN(parsed) ? null : parsed
      } else {
        values[key] = String(value)
      }
      this.draft = { ...this.draft, values }
    },
    clearValues() {
      this.draft = { ...this.draft, values: {} }
    },
    payload() {
      return {
        name: this.draft.name.trim(),
        description: this.draft.description || '',
        tier: this.draft.tier,
        values: this.draft.values || {}
      }
    },
    async save() {
      const api = this.api()
      if (!api || this.saving) return
      this.saving = true
      this.error = null
      try {
        const payload = this.payload()
        const saved = this.isNew
          ? await api.create(payload)
          : await api.save(payload.name, payload)
        // The connection layer resolves with the backend error envelope
        // (`{status_code, message}`) instead of throwing, so a rejected save
        // used to look like a silent no-op. Fail loudly instead.
        this.assertOk(saved)
        await this.load()
        const fresh = this.efforts.find(item => item.name === saved.name)
        if (fresh) this.edit(fresh)
        this.draft = { ...this.draft, builtin: !!saved.builtin }
        this.$ui?.addNotification?.({
          text: `Effort '${saved.name}' saved`,
          type: 'success'
        })
      } catch (error) {
        this.error = error?.message || 'Could not save the effort'
      } finally {
        this.saving = false
      }
    },
    /**
     * Throw when the response is the backend error envelope instead of the
     * expected payload.
     * @param {Object} response - API response.
     */
    assertOk(response) {
      if (!response || response.status_code || (!response.name && !response.deleted)) {
        throw new Error(response?.message || 'The server rejected the request')
      }
      return response
    },
    async remove() {
      const api = this.api()
      if (!api || this.saving || !this.draft.name) return
      if (!window.confirm(`Delete the effort '${this.draft.name}'?`)) return
      this.saving = true
      this.error = null
      try {
        // The connection layer resolves the backend envelope
        // (`{status_code, message}`) instead of throwing, so a refused delete
        // (409: built-in or still linked to a profile) must be inspected here.
        // A success may carry the deleted name or no body at all.
        const deleted = await api.delete(this.draft.name)
        if (deleted && deleted.status_code) {
          throw new Error(deleted.message || 'The server rejected the request')
        }
        this.draft = EMPTY_DRAFT()
        await this.load()
      } catch (error) {
        this.error = error?.message || 'Could not delete the effort'
      } finally {
        this.saving = false
      }
    }
  }
}
</script>

